//! Bounded, lossless cache of windows generated by the interactive Atlas map.
use super::super::atlas_surface::Raster;
use super::{HeightGrid, Region};
use rusqlite::{Connection, OpenFlags, OptionalExtension, params};
use std::{
    fs,
    path::{Path, PathBuf},
    sync::{Arc, OnceLock, mpsc},
    time::{Duration, UNIX_EPOCH},
};

const FILE_NAME: &str = "atlas_recent_views_v1.sqlite";
const APPLICATION_ID: i32 = 0x314b4156;
// Increment when the unlit elevation palette changes. Heights stay reusable.
const MATERIAL_VERSION: i32 = 1;
const MAX_PIXELS: usize = 32_020_000;
type Result<T> = std::result::Result<T, String>;

pub(super) struct Saved {
    pub grid: HeightGrid,
    pub colors: Option<Vec<u8>>,
}

#[derive(Clone)]
pub(super) struct Ticket {
    path: PathBuf,
    key: String,
    region: Region,
    size: [usize; 2],
    files: Vec<PathBuf>,
}
fn identity(region: Region, size: [usize; 2], files: &[PathBuf]) -> Result<String> {
    let sources: Vec<_> = files
        .iter()
        .map(|p| {
            let metadata = fs::metadata(p).map_err(|e| e.to_string())?;
            Ok((
                fs::canonicalize(p).map_err(|e| e.to_string())?,
                metadata.len(),
                metadata
                    .modified()
                    .map_err(|e| e.to_string())?
                    .duration_since(UNIX_EPOCH)
                    .map_err(|e| e.to_string())?
                    .as_nanos(),
            ))
        })
        .collect::<Result<_>>()?;
    serde_json::to_string(&(1, region.0, size, sources)).map_err(|e| e.to_string())
}
fn validate(c: &Connection) -> Result<()> {
    let app: i32 = c
        .pragma_query_value(None, "application_id", |r| r.get(0))
        .map_err(|e| e.to_string())?;
    let version: i32 = c
        .pragma_query_value(None, "user_version", |r| r.get(0))
        .map_err(|e| e.to_string())?;
    if app != APPLICATION_ID || version != 1 {
        return Err("Unrecognized Atlas recent-view cache".into());
    }
    Ok(())
}
impl Ticket {
    pub(super) fn new(
        derived: &Path,
        region: Region,
        size: [usize; 2],
        files: Vec<PathBuf>,
    ) -> Result<Self> {
        if size.iter().any(|&n| n == 0 || n > 8192) || size[0].saturating_mul(size[1]) > MAX_PIXELS
        {
            return Err("Atlas recent view exceeds image budget".into());
        }
        Ok(Self {
            path: derived.join("terrain").join(FILE_NAME),
            key: identity(region, size, &files)?,
            region,
            size,
            files,
        })
    }
    pub(super) fn read(&self) -> Result<Option<Saved>> {
        if !self.path.exists() {
            return Ok(None);
        }
        let c = Connection::open_with_flags(&self.path, OpenFlags::SQLITE_OPEN_READ_ONLY)
            .map_err(|e| e.to_string())?;
        c.busy_timeout(Duration::from_millis(100))
            .map_err(|e| e.to_string())?;
        validate(&c)?;
        let row: Option<(usize, u32)> = c
            .query_row(
                "SELECT length(payload), crc FROM views WHERE key=?1",
                [&self.key],
                |r| Ok((r.get(0)?, r.get(1)?)),
            )
            .optional()
            .map_err(|e| e.to_string())?;
        let Some((length, crc)) = row else {
            return Ok(None);
        };
        let count = self.size[0] * self.size[1];
        if length > lz4_flex::block::get_maximum_output_size(count * 4) {
            return Err("Invalid Atlas recent-view size".into());
        }
        let payload: Vec<u8> = c
            .query_row("SELECT payload FROM views WHERE key=?1", [&self.key], |r| {
                r.get(0)
            })
            .map_err(|e| e.to_string())?;
        let mut metres = vec![0f32; count];
        let bytes = bytemuck::cast_slice_mut(&mut metres);
        let written =
            lz4_flex::block::decompress_into(&payload, bytes).map_err(|e| e.to_string())?;
        if written != count * 4 || crc32fast::hash(bytes) != crc {
            return Err("Damaged Atlas recent view; regenerate from original terrain".into());
        }
        #[cfg(target_endian = "big")]
        for value in &mut metres {
            *value = f32::from_bits(value.to_bits().swap_bytes());
        }
        // Older caches contain just heights. A damaged or stale material can
        // be regenerated from these verified heights without another GDAL read.
        let colors = self.read_colors(&c, count * 4).unwrap_or_else(|error| {
            eprintln!("[atlas] rebuilding cached material: {error}");
            None
        });
        Ok(Some(Saved {
            grid: HeightGrid {
                width: self.size[0],
                height: self.size[1],
                metres,
            },
            colors,
        }))
    }
    fn read_colors(&self, c: &Connection, bytes: usize) -> Result<Option<Vec<u8>>> {
        let exists: bool = c.query_row(
            "SELECT EXISTS(SELECT 1 FROM sqlite_master WHERE type='table' AND name='materials')",
            [], |r| r.get(0),
        ).map_err(|e| e.to_string())?;
        if !exists {
            return Ok(None);
        }
        let row: Option<(usize, u32, i32)> = c
            .query_row(
                "SELECT length(payload),crc,version FROM materials WHERE key=?1",
                [&self.key],
                |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?)),
            )
            .optional()
            .map_err(|e| e.to_string())?;
        let Some((length, crc, version)) = row else {
            return Ok(None);
        };
        if version != MATERIAL_VERSION {
            return Ok(None);
        }
        if length > lz4_flex::block::get_maximum_output_size(bytes) {
            return Err("Invalid Atlas material size".into());
        }
        let payload: Vec<u8> = c
            .query_row(
                "SELECT payload FROM materials WHERE key=?1",
                [&self.key],
                |r| r.get(0),
            )
            .map_err(|e| e.to_string())?;
        let mut colors = vec![0; bytes];
        let written =
            lz4_flex::block::decompress_into(&payload, &mut colors).map_err(|e| e.to_string())?;
        if written != bytes || crc32fast::hash(&colors) != crc {
            return Err("Damaged Atlas material".into());
        }
        Ok(Some(colors))
    }
    fn store(&self, raster: &Raster) -> Result<()> {
        self.store_with_budget(raster, crate::gpu_config::settings().atlas_disk_bytes)
    }
    fn store_with_budget(&self, raster: &Raster, budget: usize) -> Result<()> {
        if raster.size != self.size
            || raster.bounds != self.region.bounds()
            || identity(self.region, self.size, &self.files)? != self.key
        {
            return Err("Atlas sources changed; recent view was not cached".into());
        }
        #[cfg(target_endian = "big")]
        let swapped: Vec<f32> = raster
            .heights
            .iter()
            .map(|v| f32::from_bits(v.to_bits().swap_bytes()))
            .collect();
        #[cfg(target_endian = "big")]
        let bytes = bytemuck::cast_slice(&swapped);
        #[cfg(target_endian = "little")]
        let bytes = bytemuck::cast_slice(&raster.heights);
        let crc = crc32fast::hash(bytes);
        let payload = lz4_flex::block::compress(bytes);
        let colors_crc = crc32fast::hash(&raster.colors);
        let colors = lz4_flex::block::compress(&raster.colors);
        let incoming = payload.len() + colors.len();
        if incoming > budget {
            return Ok(());
        }
        fs::create_dir_all(self.path.parent().unwrap()).map_err(|e| e.to_string())?;
        let existed = self.path.metadata().is_ok_and(|m| m.len() > 0);
        let mut c = Connection::open(&self.path).map_err(|e| e.to_string())?;
        c.busy_timeout(Duration::from_millis(100))
            .map_err(|e| e.to_string())?;
        if existed {
            validate(&c)?;
        } else {
            c.execute_batch(&format!("PRAGMA auto_vacuum=INCREMENTAL; BEGIN IMMEDIATE; PRAGMA application_id={APPLICATION_ID}; PRAGMA user_version=1; CREATE TABLE views(key TEXT PRIMARY KEY,payload BLOB NOT NULL,crc INTEGER NOT NULL); COMMIT;")).map_err(|e| e.to_string())?;
        }
        // A separate table keeps existing height-only entries usable in place.
        c.execute_batch("PRAGMA journal_mode=WAL; PRAGMA synchronous=NORMAL; PRAGMA cache_size=-2048; CREATE TABLE IF NOT EXISTS materials(key TEXT PRIMARY KEY,payload BLOB NOT NULL,crc INTEGER NOT NULL,version INTEGER NOT NULL);").map_err(|e| e.to_string())?;
        let page_size: usize = c
            .pragma_query_value(None, "page_size", |r| r.get(0))
            .map_err(|e| e.to_string())?;
        let max_pages = (budget + budget / 4 + 256 * 1024 * 1024) / page_size;
        c.pragma_update(None, "max_page_count", max_pages)
            .map_err(|e| e.to_string())?;
        let tx = c
            .transaction_with_behavior(rusqlite::TransactionBehavior::Immediate)
            .map_err(|e| e.to_string())?;
        tx.execute("DELETE FROM views WHERE key=?1", [&self.key])
            .map_err(|e| e.to_string())?;
        tx.execute(
            "DELETE FROM materials WHERE key NOT IN (SELECT key FROM views)",
            [],
        )
        .map_err(|e| e.to_string())?;
        loop {
            let used: usize = tx.query_row(
                "SELECT coalesce(sum(length(v.payload)+coalesce(length(m.payload),0)),0) FROM views v LEFT JOIN materials m USING(key)",
                [], |r| r.get(0),
            ).map_err(|e| e.to_string())?;
            if used + incoming <= budget {
                break;
            }
            tx.execute(
                "DELETE FROM materials WHERE key=(SELECT key FROM views ORDER BY rowid LIMIT 1)",
                [],
            )
            .map_err(|e| e.to_string())?;
            tx.execute(
                "DELETE FROM views WHERE rowid=(SELECT min(rowid) FROM views)",
                [],
            )
            .map_err(|e| e.to_string())?;
        }
        tx.execute(
            "INSERT INTO views VALUES (?1,?2,?3)",
            params![self.key, payload, crc],
        )
        .map_err(|e| e.to_string())?;
        tx.execute(
            "INSERT INTO materials VALUES (?1,?2,?3,?4)",
            params![self.key, colors, colors_crc, MATERIAL_VERSION],
        )
        .map_err(|e| e.to_string())?;
        tx.commit().map_err(|e| e.to_string())?;
        c.execute_batch("PRAGMA incremental_vacuum(4096); PRAGMA wal_checkpoint(TRUNCATE);")
            .map_err(|e| e.to_string())?;
        Ok(())
    }
}

enum WriteJob {
    Store(Ticket, Arc<Raster>),
    #[cfg(test)]
    Barrier(mpsc::SyncSender<()>),
}
static WRITER: OnceLock<Option<mpsc::SyncSender<WriteJob>>> = OnceLock::new();

/// A bounded queue keeps compression and USB writes out of time-to-first-terrain.
pub(super) fn persist(ticket: Ticket, raster: Arc<Raster>) {
    if let Some(tx) = WRITER.get_or_init(|| {
        let (tx, rx) = mpsc::sync_channel::<WriteJob>(1);
        std::thread::Builder::new()
            .name("atlas-view-writer".into())
            .spawn(move || {
                for job in rx {
                    match job {
                        WriteJob::Store(ticket, raster) => {
                            if let Err(error) = ticket.store(&raster) {
                                eprintln!("[atlas] recent-view cache: {error}");
                            }
                        }
                        #[cfg(test)]
                        WriteJob::Barrier(done) => {
                            let _ = done.send(());
                        }
                    }
                }
            })
            .ok()
            .map(|_| tx)
    }) {
        let _ = tx.try_send(WriteJob::Store(ticket, raster));
    }
}

#[cfg(test)]
pub(super) fn flush() {
    if let Some(Some(tx)) = WRITER.get() {
        let (done, wait) = mpsc::sync_channel(1);
        tx.send(WriteJob::Barrier(done)).unwrap();
        wait.recv_timeout(Duration::from_secs(60)).unwrap();
    }
}

